/**
 * 3D-броски: два кубика падают поверх текста, катятся и показывают число.
 *
 * Сцена рисуется на прозрачном canvas поверх экрана текста (canvas не ловит
 * клики), поэтому кубики «лежат» прямо на странице. Физика простая: падение,
 * отскок с затуханием, затем доворот к выпавшей грани — итог всегда совпадает
 * с тем, что посчитал движок.
 */

import * as THREE from 'three';

import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

import { dieMaterials, planRoll, rotationForFace, type DiePlan } from './dice.ts';

export interface DiceSceneOptions {
  /** Длительность падения до полной остановки, секунды. */
  fall: number;
  /** Сколько держать кубики после остановки (пока читают число). */
  hold: number;
  /** Кубики остановились — можно показать результат. */
  onSettled?: () => void;
}

interface Die {
  mesh: THREE.Mesh;
  plan: DiePlan;
  shadow: THREE.Mesh;
  quaternion: THREE.Quaternion;
  position: THREE.Vector3;
  velocity: THREE.Vector3;
  spin: THREE.Vector3;
  settled: boolean;
}

const GRAVITY = -17;
const BOUNCE = 0.44;
const DIE_SIZE = 0.9;

export class DiceScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera: THREE.PerspectiveCamera;
  private readonly clock = new THREE.Clock();
  private readonly disposables: { dispose(): void }[] = [];
  private readonly shadowTexture: THREE.Texture;
  private dice: Die[] = [];
  private frame = 0;
  private started = 0;
  private phase: 'idle' | 'roll' | 'settled' = 'idle';
  private settledFired = false;
  private disposed = false;
  private values: number[] = [];

  constructor(private readonly canvas: HTMLCanvasElement, private readonly options: DiceSceneOptions) {
    this.renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
    this.renderer.setClearAlpha(0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.renderer.shadowMap.enabled = false;

    this.camera = new THREE.PerspectiveCamera(42, 1, 0.1, 60);
    this.camera.position.set(0, 5.0, 6.2);
    this.camera.lookAt(0, 0.55, 0.4);

    // свет: мягкая заливка снизу, жёсткий ключ сверху-слева и тёплый отблеск справа,
    // плюс контровой сзади — без него грани выглядят плоскими
    this.scene.add(new THREE.HemisphereLight(0xfff4e2, 0x6b6152, 1.0));
    const key = new THREE.DirectionalLight(0xfff3dd, 2.9);
    key.position.set(-3.4, 8.2, 5.4);
    this.scene.add(key);
    const fill = new THREE.DirectionalLight(0xffd6a2, 1.2);
    fill.position.set(5.0, 2.0, 3.2);
    this.scene.add(fill);
    // контровой свет тёплый: холодный давал синий отблеск на точках верхней грани
    const rim = new THREE.DirectionalLight(0xf3e6d2, 1.1);
    rim.position.set(1.6, 3.0, -6.0);
    this.scene.add(rim);

    this.shadowTexture = DiceScene.shadowTexture();
    this.disposables.push(this.shadowTexture);
  }

  private static shadowTexture(): THREE.Texture {
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 128;
    const context = canvas.getContext('2d')!;
    const gradient = context.createRadialGradient(64, 64, 4, 64, 64, 64);
    gradient.addColorStop(0, 'rgba(28, 22, 16, 0.55)');
    gradient.addColorStop(0.55, 'rgba(28, 22, 16, 0.22)');
    gradient.addColorStop(1, 'rgba(28, 22, 16, 0)');
    context.fillStyle = gradient;
    context.fillRect(0, 0, 128, 128);
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return texture;
  }

  /** Запустить бросок: значения приходят от движка, зерно — для повторяемости. */
  roll(values: number[], seed = 1): void {
    this.clear();
    this.values = values.slice();
    this.settledFired = false;
    this.phase = 'roll';
    this.started = this.clock.getElapsedTime();
    this.dice = planRoll(values, seed, DIE_SIZE).map((plan) => {
      const materials = dieMaterials(64);
      this.disposables.push(...materials.disposables);
      // скруглённые рёбра: кубик читается как настоящая кость, а не как куб
      const geometry = new RoundedBoxGeometry(DIE_SIZE, DIE_SIZE, DIE_SIZE, 4, DIE_SIZE * 0.12);
      this.disposables.push(geometry);
      const mesh = new THREE.Mesh(geometry, materials.faces);
      mesh.position.copy(plan.start);
      this.scene.add(mesh);

      const shadowGeometry = new THREE.PlaneGeometry(DIE_SIZE * 2.1, DIE_SIZE * 2.1);
      const shadowMaterial = new THREE.MeshBasicMaterial({
        map: this.shadowTexture, transparent: true, depthWrite: false, opacity: 0.9,
      });
      const shadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
      shadow.rotation.x = -Math.PI / 2;
      this.scene.add(shadow);
      this.disposables.push(shadowGeometry, shadowMaterial);

      return {
        mesh,
        plan,
        shadow,
        position: plan.start.clone(),
        velocity: plan.velocity.clone(),
        spin: plan.spin.clone(),
        quaternion: new THREE.Quaternion(),
        settled: false,
      };
    });
    this.canvas.style.opacity = '1';
    this.loop();
  }

  /** Текущее состояние — для тестов и отладки. */
  get state(): { phase: string; values: number[] } {
    return { phase: this.phase, values: this.values.slice() };
  }

  resize(width: number, height: number, pixelRatio = 1): void {
    this.renderer.setPixelRatio(Math.min(pixelRatio, 2));
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / Math.max(1, height);
    // на узком экране отодвигаем камеру, чтобы оба кубика остались в кадре
    const pull = Math.max(0, 0.9 - this.camera.aspect) * 3.4;
    this.camera.position.set(0, 5.0 + pull * 0.35, 6.2 + pull);
    this.camera.lookAt(0, 0.55, 0.4);
    this.camera.updateProjectionMatrix();
  }

  private clear(): void {
    for (const die of this.dice) {
      this.scene.remove(die.mesh);
      this.scene.remove(die.shadow);
    }
    this.dice = [];
    this.values = [];
    this.phase = 'idle';
  }

  private step(die: Die, time: number, delta: number, settleFrom: number): void {
    const half = DIE_SIZE / 2;
    const elapsed = time - this.started - die.plan.delay;
    if (elapsed < 0) {
      die.mesh.visible = false;
      die.shadow.visible = false;
      return;
    }
    die.mesh.visible = true;
    die.shadow.visible = true;

    const settle = elapsed > settleFrom;
    if (settle) {
      // доворот к выпавшей грани: последние доли секунды кубик «ложится» на число
      const k = Math.min(1, (elapsed - settleFrom) / Math.max(0.001, this.options.fall - settleFrom));
      const ease = 1 - Math.pow(1 - k, 3);
      const target = rotationForFace(die.plan.value, die.plan.restSpin);
      // доводим долей от текущего положения к целевому: без рывка на последнем кадре
      die.mesh.quaternion.slerp(target, Math.min(1, ease * 0.35 + 0.08));
      die.mesh.position.lerp(die.plan.rest, Math.min(1, ease * 0.35 + 0.08));
      if (k >= 1) {
        die.mesh.quaternion.copy(target);
        die.mesh.position.copy(die.plan.rest);
        die.settled = true;
      }
    } else {
      die.velocity.y += GRAVITY * delta;
      die.position.addScaledVector(die.velocity, delta);
      if (die.position.y < half) {
        die.position.y = half;
        die.velocity.y = Math.abs(die.velocity.y) * BOUNCE;
        die.velocity.x *= 0.74;
        die.velocity.z *= 0.74;
        die.spin.multiplyScalar(0.62);
      }
      die.mesh.position.copy(die.position);
      const spinStep = new THREE.Quaternion().setFromEuler(new THREE.Euler(
        die.spin.x * delta, die.spin.y * delta, die.spin.z * delta,
      ));
      die.quaternion.multiply(spinStep);
      die.mesh.quaternion.copy(die.quaternion);
    }

    // тень под кубиком: чем выше, тем шире и бледнее
    const height = Math.max(0, die.mesh.position.y - half);
    const spread = 1 + height * 0.22;
    die.shadow.position.set(die.mesh.position.x, 0.002, die.mesh.position.z);
    die.shadow.scale.setScalar(Math.max(0.4, spread * (1 - height * 0.05)));
    (die.shadow.material as THREE.MeshBasicMaterial).opacity = Math.max(0.08, 0.5 - height * 0.06);
  }

  private loop = (): void => {
    this.frame = requestAnimationFrame(this.loop);
    if (document.hidden || this.phase === 'idle') return;
    const time = this.clock.getElapsedTime();
    const delta = Math.min(this.clock.getDelta(), 0.05);
    const settleFrom = Math.max(0, this.options.fall - 0.5);
    for (const die of this.dice) this.step(die, time, delta, settleFrom);
    this.renderer.render(this.scene, this.camera);

    if (!this.settledFired && this.dice.length > 0 && this.dice.every((die) => die.settled)) {
      // флаг ставим сразу: таймер должен взвестись ровно один раз
      this.settledFired = true;
      window.setTimeout(() => {
        if (this.disposed) return;
        this.phase = 'settled';
        this.options.onSettled?.();
      }, this.options.hold * 1000);
    }
  };

  dispose(): void {
    this.disposed = true;
    cancelAnimationFrame(this.frame);
    this.clear();
    for (const item of this.disposables) item.dispose();
    this.disposables.length = 0;
    this.renderer.dispose();
  }
}
