/**
 * Кубики: геометрия, грани и «физика» падения.
 *
 * Модуль сознательно не зависит от сцены и рендера — только математика и
 * материалы. Поэтому его можно проверять юнит-тестами: какие грани
 * противоположны, куда встаёт выпавшая грань, как раскладываются точки.
 */

import * as THREE from 'three';

/**
 * Порядок материалов в BoxGeometry: +X, −X, +Y, −Y, +Z, −Z.
 * В этом же порядке перечислены значения граней, чтобы 1 была напротив 6,
 * 2 напротив 5 и 3 напротив 4 (сумма 7, как у обычного кубика).
 */
export const FACE_ORDER = [1, 6, 2, 5, 3, 4] as const;

/** Куда смотрит нормаль каждой грани в локальных координатах кубика. */
export const FACE_NORMALS: Record<number, THREE.Vector3> = {
  1: new THREE.Vector3(1, 0, 0),
  6: new THREE.Vector3(-1, 0, 0),
  2: new THREE.Vector3(0, 1, 0),
  5: new THREE.Vector3(0, -1, 0),
  3: new THREE.Vector3(0, 0, 1),
  4: new THREE.Vector3(0, 0, -1),
};

/** Раскладка точек на грани: строки сверху вниз, столбцы слева направо. */
const PIP_LAYOUT: Record<number, [number, number][]> = {
  1: [[0, 0]],
  2: [[-1, -1], [1, 1]],
  3: [[-1, -1], [0, 0], [1, 1]],
  4: [[-1, -1], [-1, 1], [1, -1], [1, 1]],
  5: [[-1, -1], [-1, 1], [0, 0], [1, -1], [1, 1]],
  6: [[-1, -1], [-1, 0], [-1, 1], [1, -1], [1, 0], [1, 1]],
};

export function pipLayout(value: number): [number, number][] {
  const layout = PIP_LAYOUT[value];
  if (!layout) throw new Error(`нет раскладки для грани ${value}`);
  return layout;
}

/** Текстура грани: светлый квадрат и тёмные точки. */
export function pipTexture(value: number, size = 256): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const context = canvas.getContext('2d')!;
  context.fillStyle = '#f2e7d2';
  context.fillRect(0, 0, size, size);
  // объём грани: светлее сверху, темнее снизу
  const edge = context.createLinearGradient(0, 0, 0, size);
  edge.addColorStop(0, 'rgba(255,255,255,0.35)');
  edge.addColorStop(0.55, 'rgba(255,255,255,0)');
  edge.addColorStop(1, 'rgba(96,74,48,0.22)');
  context.fillStyle = edge;
  context.fillRect(0, 0, size, size);

  const step = size / 3.35;
  const radius = size * 0.083;
  for (const [column, row] of pipLayout(value)) {
    const x = size / 2 + column * step;
    const y = size / 2 - row * step;
    // углубление: светлая фаска снизу-справа и тень сверху-слева
    context.beginPath();
    context.arc(x + radius * 0.14, y + radius * 0.16, radius * 1.12, 0, Math.PI * 2);
    context.fillStyle = 'rgba(255, 250, 235, 0.85)';
    context.fill();
    context.beginPath();
    context.arc(x - radius * 0.08, y - radius * 0.1, radius * 1.06, 0, Math.PI * 2);
    context.fillStyle = 'rgba(92, 68, 42, 0.35)';
    context.fill();
    context.beginPath();
    context.arc(x, y, radius, 0, Math.PI * 2);
    context.fillStyle = '#2b1d13';
    context.fill();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 8;
  return texture;
}

export interface DieMaterials {
  faces: THREE.Material[];
  disposables: { dispose(): void }[];
}

/** Материалы шести граней: индекс в массиве — сторона BoxGeometry. */
export function dieMaterials(size = 256): DieMaterials {
  const faces: THREE.Material[] = [];
  const disposables: { dispose(): void }[] = [];
  for (const value of FACE_ORDER) {
    const texture = pipTexture(value, size);
    const material = new THREE.MeshStandardMaterial({
      map: texture, roughness: 0.42, metalness: 0.02,
    });
    faces.push(material);
    disposables.push(material, texture);
  }
  return { faces, disposables };
}

/**
 * Поворот, при котором выпавшая грань смотрит вверх.
 *
 * Сначала совмещаем нормаль грани с осью +Y, потом доворачиваем вокруг
 * вертикали — чтобы кубик не выглядел каждый раз одинаково.
 */
export function rotationForFace(value: number, spin = 0): THREE.Quaternion {
  const normal = FACE_NORMALS[value];
  if (!normal) throw new Error(`нет грани ${value}`);
  const up = new THREE.Vector3(0, 1, 0);
  const quaternion = new THREE.Quaternion().setFromUnitVectors(normal.clone().normalize(), up);
  quaternion.premultiply(new THREE.Quaternion().setFromAxisAngle(up, spin));
  return quaternion;
}

export interface DiePlan {
  value: number;
  /** С какой стороны и как кубик влетает в кадр. */
  start: THREE.Vector3;
  velocity: THREE.Vector3;
  spin: THREE.Vector3;
  /** Пауза перед броском, секунды. */
  delay: number;
  /** Куда кубик встанет. */
  rest: THREE.Vector3;
  restSpin: number;
}

function random(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

/**
 * План броска: детерминированный — по значениям и зерну. Благодаря этому
 * один и тот же бросок всегда проигрывается одинаково (и это проверяется тестом).
 */
export function planRoll(values: number[], seed = 1, dieSize = 1): DiePlan[] {
  const next = random(seed * 7919 + values.reduce((sum, value) => sum + value, 0) * 104729);
  const gap = dieSize * 1.6;
  return values.map((value, index) => {
    const side = index % 2 === 0 ? -1 : 1;
    const start = new THREE.Vector3(
      side * (gap / 2 + next() * 0.6),
      4.2 + next() * 1.6,
      -1.2 - next() * 1.4,
    );
    return {
      value,
      start,
      velocity: new THREE.Vector3(
        -side * (0.9 + next() * 1.4),
        -0.6 - next() * 0.8,
        1.6 + next() * 2.0,
      ),
      spin: new THREE.Vector3(
        (next() - 0.5) * 22,
        (next() - 0.5) * 26,
        (next() - 0.5) * 22,
      ),
      delay: index * 0.12,
      rest: new THREE.Vector3(side * gap * 0.5, dieSize * 0.5, 0.35 + next() * 0.2),
      restSpin: next() * Math.PI * 2,
    };
  });
}
